#---------- Parse Track File ----------

def read_track(text):
    track = []
    for line in text.splitlines():
        line = line.strip()
        if not line:
            continue
        parts = line.replace(',', '\t').split('\t')
        track.append([float(parts[0]), float(parts[1]), float(parts[2])])
    return track

#---------- Functions ----------

def quadratic_formula(a, b, c):
    discriminant = b**2 - 4*a*c
    if discriminant < 0:
        return None
    root = np.sqrt(discriminant)
    return [(-b + root)/(2*a), (-b - root)/(2*a)]

def quadratic_function(coefficient, x):
    return coefficient[0] * (x**2) + coefficient[1] * x + coefficient[2]

def seconds_to_ms(seconds):
    minutes = int(seconds // 60)
    seconds = seconds % 60
    return f'{minutes}:{seconds:.3f}'

#---------- Car Class ----------

class Car:
    def __init__(self, w, cl, cd, fa, tw, wr, tq, gr):
        self.weight = w
        self.mass = w / g
        self.c_lift = -1 * cl # Change from standard sign convention
        self.c_drag = cd
        self.frontal_area = fa
        self.tw = (tw + 6) * in_to_ft
        self.wheel_radius = wr * in_to_ft
        self.torque = tq * nm_to_ftlb * torque_scale_factor
        self.gear_ratio = gr
        self.efficiency = n_powertrain
        # Tire coefficients/parameters for Hoosier 16x6-7 at 12 psi:
        self.pdy1 = pdy1                # Lateral friction Muy at nominal load (Fz0)
        self.pdy2 = pdy2                # Variation of friction Muy with load
        self.pdy3 = -11.5817            # Variation of friction Muy with camber squared
        self.fz0_y = 149.948            # Nominal tire load, lbf
        self.pdx1 = pdx1                # Longitudinal friction Mux at nominal load (Fz0)
        self.pdx2 = pdx2                # Variation of friction Mux with load
        self.pdx3 = 15.5786             # Variation of friction Mux with camber squared
        self.fz0_x = 146.126            # Nominal tire load from long data, lbf
        self.scaling_factor = 0.6       # Muy scaling factor
        self.camber = math.radians(2)   # Camber angle
        self.dt = 0.01                  # Integration time step, s

    # Downforce in lbf based on velocity
    def downforce(self, v):
        return 0.5 * self.c_lift * rho * self.frontal_area * v**2

    # Drag in lbf based on velocity
    def drag(self, v):
        return 0.5 * self.c_drag * rho * self.frontal_area * v**2

    # Load dependant lateral friction coefficient
    def mu_y(self, fz_tire):
        dfz = (fz_tire - self.fz0_y) / self.fz0_y
        return (self.pdy1 + self.pdy2 * dfz) * (1 + self.pdy3 * self.camber**2) * self.scaling_factor

    # Load dependant longitudinal friction coefficient
    def mu_x(self, fz_tire):
        dfz = (fz_tire - self.fz0_x) / self.fz0_x
        return (self.pdx1 + self.pdx2 * dfz) * (1 + self.pdx3 * self.camber**2) * self.scaling_factor

    # Finds maximum theoretical cornering velocity based on available grip and corner radius
    def cornering_speed(self, r):
        r = r + self.tw / 2     # Assumes width of track = car trackwidth
        v = 35                  # Initial velocity guess, ft/s
        for _ in range(1000000):
            fz_tire = (self.weight + self.downforce(v)) / 4     # Total Fz per tire, including downforce
            mu = self.mu_y(fz_tire)                             # Load dependent Mu_y
            # Creates quadratic equation to find the velocity at which lateral force required = lateral force available
            # Based on: (m * V^2) / r = Mu * (m * g + (0.5 * C_l * Rho * FA * V^2))
            # Which can be rearranged to the following quadratic equation:
            # ((m/r)-(0.5 * C_l * Rho * FA))V^2  -  (Mu * m * g)  =  0
            a = (self.mass / r) - mu * (0.5 * abs(self.c_lift) * rho * self.frontal_area)
            c = -mu * self.weight
            roots = quadratic_formula(a, 0, c)
            if roots is None:
                return None
            v_new = max(roots)
            # Function will iterate until v and v_new converge
            if abs(v_new - v) < 0.0001:
                return v_new
            v = v_new
        return v

    # Determines cornering based on radius and total turn angle
    # Currently only used for calculating skidpad time
    def cornering_time(self, r, theta):
        v = self.cornering_speed(r)
        if v is None:
            return None
        r = r + self.tw/2
        d = 2 * pi * r * (theta / 360)
        time = d / v
        return time

    # Calculates time to drive entire distance of a straight
    # Currently only used for estimating accel time
    def straight_time(self, v_0, v_f, length):
        t = 0
        d = 0
        v = v_0
        while d < length:
            fz_tire = (self.weight + self.downforce(v)) / 4
            f_long_max = self.mu_x(fz_tire) * (self.weight + self.downforce(v))
            f_drive = min((self.torque * self.gear_ratio / self.wheel_radius), f_long_max)
            a = (f_drive - self.drag(v)) / self.mass
            v += a * self.dt
            d += v * self.dt
            t += self.dt
        if v_f == -1:
            return t
        return t

    # Determines velocity limit at each interval across an entire lap
    # This is the main function used for estimating lap times for a given track
    def velocity_profile(self, rows):
        n = len(rows)
        row_spacing = rows[1][1] - rows[0][1]   # Feet covered between each interval in track file
        lap_length = rows[-1][1] + row_spacing  # Estimated lap length, ft

        # Initialize list for cumulative distance and corner radius at each point
        distances = []
        radii = []
        for row in rows:
            distances.append(row[1])
            radii.append(row[2])

        v_max = [] # List of velocity limits at each point
        for r in radii:
            if abs(r) >= straight_threshold:        # This guesses whether a point along the lap is part of a straight or a corner
                v_max.append(float('inf'))          # If a point is deemed to be on a straight, there is no velocity limit
            else:
                vl = self.cornering_speed(abs(r))   # If a point is deemed to be along a corner, its max velocity is calculated
                v_max.append(vl)

        # Duplicates all track points to create a two lap window
        extended_distances = distances
        lap_two = []
        for d in distances:
            lap_two.append(d + lap_length)
        extended_distances += lap_two
        extended_radii = radii * 2
        extended_v_max = v_max * 2
        extended_v = extended_v_max[:]

        # Forward accel pass; determines max velocity at each point based on acceleration and previous velocity
        for i in range(1, 2 * n):
            ds = extended_distances[i] - extended_distances[i - 1]
            v_prev = extended_v[i - 1]
            r = extended_radii[i]
            # Previous point is on a straight with no velocity limit yet (e.g. track starts on a straight),
            # so there is no acceleration limit to apply. Keep this point's pure cornering/straight limit.
            if math.isinf(v_prev):
                extended_v[i] = extended_v_max[i]
                continue
            fz_tire = (self.weight + self.downforce(v_prev)) / 4
            mu_long = self.mu_x(fz_tire)
            mu_lat = self.mu_y(fz_tire)
            f_lateral = (self.mass * v_prev**2) / abs(r)
            f_lateral_max = mu_lat * (self.weight + self.downforce(v_prev))
            # Maximum longitudinal force from friction ellipse
            if f_lateral_max <= 0:
                return None
            lateral_ratio = f_lateral / f_lateral_max
            lateral_ratio = max(-1, min(1, lateral_ratio))
            friction_ellipse = math.sqrt(1 - lateral_ratio**2)
            f_long_max = (
                mu_long * (self.weight + self.downforce(v_prev))
            ) * max(0, friction_ellipse)
            # Finds force limit of powertrain and traction. Smaller value is actual driving force limit
            f_drive = min((self.torque * self.gear_ratio / self.wheel_radius), f_long_max)
            # Finds acceleration limit, accounting for drag
            a = (f_drive - self.drag(v_prev)) / self.mass
            # Finds new velocity using V^2 = V_0^2 + 2ax
            radicand = v_prev**2 + 2 * a * ds
            if radicand < 0:
                return None
            v_new = math.sqrt(radicand)
            # Compares v_new to pure cornering velocity limit and keeps lesser value
            extended_v[i] = min(extended_v_max[i], v_new)

        extended_v_accel = extended_v[n:]   # Discards first lap of data, keeps only second
        extended_v_decel = extended_v_max[:]

        # Backwards decel pass; determines max velocity at each point based on decel and max velocity at point after
        for i in range(2 * n - 2, -1, -1):
            ds = extended_distances[i + 1] - extended_distances[i]
            v_next = extended_v_decel[i + 1]
            r = extended_radii[i]
            # Following point has no velocity limit (e.g. track ends on a straight), so there is no
            # braking limit to apply. Keep this point's pure cornering/straight limit.
            if math.isinf(v_next):
                continue
            fz_tire = (self.weight + self.downforce(v_next)) / 4
            mu_long = self.mu_x(fz_tire)
            mu_lat = self.mu_y(fz_tire)
            f_lateral = (self.mass * v_next**2) / abs(r)
            f_lateral_max = mu_lat * (self.weight + self.downforce(v_next))
            # Maximum braking force from friction ellipse
            if f_lateral_max <= 0:
                return None
            lateral_ratio = f_lateral / f_lateral_max
            lateral_ratio = max(-1, min(1, lateral_ratio))
            friction_ellipse = math.sqrt(1 - lateral_ratio**2)
            f_brake_max = (
                mu_long * (self.weight + self.downforce(v_next))
            ) * max(0, friction_ellipse)
            # Deceleration from braking and drag
            a_decel = (self.drag(v_next) + f_brake_max) / self.mass
            # Finds new velocity using V^2 = V_0^2 + 2ax
            v_new = math.sqrt(v_next**2 + 2 * a_decel * ds)
            # Compares velocity determined by braking to pure cornering limit, keeps lesser value
            extended_v_decel[i] = min(extended_v_decel[i], v_new)

        # Discards second lap of data
        v_decel = extended_v_decel[:n]
        # Returns lowest velocity from cornering, accel, and decel calculations
        return [min(v_max[i], extended_v_accel[i], v_decel[i]) for i in range(n)]

    # Calculates power and energy usage throughout a lap
    def power_profile(self, rows):
        n = len(rows)
        v_actual = self.velocity_profile(rows)
        if v_actual is None:
            return None, None
        distances = []
        for row in rows:
            distances.append(row[1])
        row_spacing = distances[1] - distances[0]
        lap_length = distances[-1] + row_spacing
        distances_loop = distances + [lap_length]
        # Adds velocity connecting last point to first. Sets velocity at end of lap to velocity at start of lap
        v_loop = v_actual + [v_actual[0]]
        power = []
        energy = 0.0
        for i in range(n):
            ds = distances_loop[i + 1] - distances_loop[i]
            v_avg = (v_loop[i + 1] + v_loop[i]) / 2
            a_x = (v_loop[i + 1]**2 - v_loop[i]**2) / (2 * ds)
            f_x = self.mass * a_x + self.drag(v_avg)
            p = max(0, (f_x * v_avg / self.efficiency) * ftlbfs_to_kw)
            power.append(p)
            energy += (p * ds / v_avg) / 3600
        return power, energy

    def lap_time(self, rows):
        t = 0.0
        n = len(rows)
        v_actual = self.velocity_profile(rows)
        if v_actual is None:
            return None, None, None
        distances = []
        for row in rows:
            distances.append(row[1])
        row_spacing = distances[1] - distances[0]
        lap_length = distances[-1] + row_spacing
        distances_loop = distances + [lap_length]
        # Adds velocity connecting last point to first. Sets velocity at end of lap to velocity at start of lap
        v_loop = v_actual + [v_actual[0]]
        for i in range(1, n + 1):
            ds = distances_loop[i] - distances_loop[i - 1]
            v_avg = (v_loop[i] + v_loop[i - 1]) / 2
            t += ds / v_avg
        lap_count = 72178.5 / lap_length
        total_time = t * lap_count
        return t, total_time, lap_count

#---------- GUI Setup ----------

class LapSimApp(tk.Tk):
    # Initializing class
    def __init__(self, master, track):
        self.master = master
        self.track = track
        self.master.title("Lap Sim")
        self.master.state('zoomed')     # Open the GUI maximized to fill the screen
        self.master.configure(bg='#005035')    # GUI background is Charlotte Green
        self.param_vals = {}    # Dictionary containing paramater names and their values
        self.event_times = {}   # Dictionary containing event names and times
        self.point_table = {}   # Dictionary containing point calculator results
        self.ui_style()
        self.widgets_layout()

    # Defining appearence of each widget type
    def ui_style(self):
        style = ttk.Style(self.master)
        style.theme_use("classic")
        style.configure('TFrame', background='#005035')
        style.configure('TLabel', background='#005035', foreground='#FFFFFF', font=('Helvetica', 16))
        style.configure('Header.TLabel', background='#005035', foreground='#F1E6B2', font=('Helvetica', 22, ' bold'))
        style.configure('Result.TLabel', background='#005035', foreground='#10EFE5', font=('Helvetica', 22, ' bold'))
        style.configure('TButton', background='#F1E6B2', foreground='#005035', font=('Helvetica', 12, ' bold'))
        style.configure('TEntry', background='#FFFFFF', font=('Helvetica', 14))

    # Creating widgets
    def widgets_layout(self):
        #---------- Parameter Frame ----------
        params_frame = ttk.Frame(self.master, style='TFrame')
        params_frame.place(relx=0.02, rely=0.03, relwidth=0.55, relheight=0.34, anchor='nw')
        ttk.Label(params_frame, text="Car Parameters:", style='Header.TLabel').grid(row=0, column=0, columnspan=4, sticky='w')
        self.compute_button = ttk.Button(params_frame, text='Compute', style='TButton', command=self.compute)
        self.compute_button.grid(row=5, column=0, columnspan=2, sticky='w', padx=5, pady=(2, 5))
        entry_space = 15
        parameter_layout = [
            ('Weight (lbs)', 'weight_var', weight, 'weight'),
            ('Lift Coefficient', 'cl_var', c_lift, 'c_lift'),
            ('Drag Coefficient', 'cd_var', c_drag, 'c_drag'),
            ('Frontal Area (ft^2)', 'fa_var', frontal_area, 'frontal_area'),
            ('Track Width (in)', 'tw_var', track_width, 'track_width'),
            ('Wheel Radius (in)', 'rwheel_var', wheel_radius, 'wheel_radius'),
            ('Torque (Nm)', 'torque_var', torque, 'torque'),
            ('Gear Ratio', 'gr_var', gear_ratio, 'gear_ratio')
        ]
        for index, (label, var_name, default, key) in enumerate(parameter_layout):
            column_group = 0 if index < 4 else 2
            row = (index % 4) + 1
            var = tk.StringVar(value=str(default))
            setattr(self, var_name, var)
            self.param_vals[key] = var
            ttk.Label(params_frame, text=label, style='TLabel').grid(
                row=row, column=column_group, sticky='w', padx=5, pady=6
            )
            ttk.Entry(params_frame, textvariable=var, style='TEntry', width=10).grid(
                row=row, column=column_group + 1, sticky='e', padx=(5, entry_space), pady=6
            )
        params_frame.grid_columnconfigure(0, weight=1)
        params_frame.grid_columnconfigure(1, weight=0)
        params_frame.grid_columnconfigure(2, weight=1)
        params_frame.grid_columnconfigure(3, weight=0)
        #---------- Result Frame ----------
